"""Validate and export invoice JSON with total for the billing API (pydantic 1.10)."""
from datetime import datetime, timezone
from decimal import Decimal, ROUND_DOWN
from typing import List, Union

from pydantic import BaseModel, validator, ValidationError, root_validator

# Reuse Line and Invoice from json_export with slight extension for quantity >=1 and unit_price >=0
# We redefine here to add stricter validation as requested.

def _utc_z(dt: datetime) -> str:
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")


class Line(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @validator("quantity")
    def quantity_must_be_at_least_1(cls, v):
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @validator("unit_price", pre=True)
    def unit_price_must_be_decimal_and_nonnegative(cls, v):
        # Accept str/int/float, convert to Decimal
        try:
            dec = Decimal(v)
        except Exception:
            raise ValueError("unit_price must be a decimal number")
        if dec < 0:
            raise ValueError("unit_price must be >= 0")
        # Quantize to 2 decimal places without rounding up
        dec = dec.quantize(Decimal("0.01"), rounding=ROUND_DOWN)
        return dec


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v):
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError("issued_at must be a valid ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be a datetime or ISO 8601 string")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        # Remove microseconds for second precision
        dt = dt.replace(microsecond=0)
        return dt

    @root_validator
    def check_lines_not_empty(cls, values):
        lines = values.get("lines")
        if not lines:
            raise ValueError("lines must not be empty")
        return values


def export_invoice(data: dict) -> str:
    """
    Validate invoice data and return JSON text for billing API with total included.

    Input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive treated as UTC)
      - lines: list of dicts with sku (str), quantity (int >=1), unit_price (decimal >=0 as str/int/float)

    Output JSON keys:
      - number (str)
      - issued_at (str, formatted YYYY-MM-DDTHH:MM:SSZ UTC)
      - lines: list of dicts with sku, quantity, unit_price (string with exactly two decimals)
      - total: string with exactly two decimals (sum of quantity * unit_price)

    Raises ValueError on invalid input.
    """
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        raise ValueError(e)

    # Prepare output dict
    out = {
        "number": invoice.number,
        "issued_at": _utc_z(invoice.issued_at),
        "lines": [],
    }

    total = Decimal("0.00")
    for line in invoice.lines:
        # Format unit_price as string with exactly two decimals
        unit_price_str = f"{line.unit_price:.2f}"
        out["lines"].append({
            "sku": line.sku,
            "quantity": line.quantity,
            "unit_price": unit_price_str,
        })
        total += line.unit_price * line.quantity

    # Format total as string with two decimals
    total_str = f"{total.quantize(Decimal('0.01')):.2f}"
    out["total"] = total_str

    import json
    return json.dumps(out, separators=(",", ":"))

from typing import List, Optional

from pydantic import BaseModel, validator


class ImportProfile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @validator("display_name")
    def clean_display_name(cls, value):
        value = " ".join(value.split())
        if not value:
            raise ValueError("display_name must not be blank")
        return value

    @validator("zip_code", pre=True)
    def zip_code_to_str(cls, value):
        return str(value)


def import_profiles(rows: list) -> list:
    valid_profiles = []
    for row in rows:
        try:
            profile = ImportProfile.parse_obj(row)
        except Exception:
            continue
        valid_profiles.append(profile.dict())
    return valid_profiles

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import List, Union
from pydantic import BaseModel, Field, ValidationError, field_validator


class InvoiceLine(BaseModel):
    sku: str
    quantity: int = Field(..., ge=1)
    unit_price: Decimal = Field(..., ge=0)

    @field_validator('unit_price', mode='before')
    @classmethod
    def validate_unit_price(cls, v):
        # Accept str, int, float; convert to Decimal
        try:
            dec = Decimal(str(v))
        except Exception as e:
            raise ValueError(f"unit_price must be a decimal convertible value: {v}") from e
        if dec < 0:
            raise ValueError("unit_price must be >= 0")
        return dec

    def unit_price_str(self) -> str:
        # Format with exactly two decimals, rounding half up
        return f"{self.unit_price.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)}"


class Invoice(BaseModel):
    number: str
    issued_at: Union[datetime, str]
    lines: List[InvoiceLine]

    model_config = {
        "from_attributes": True,
    }

    @field_validator('issued_at', mode='before')
    @classmethod
    def validate_issued_at(cls, v):
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                # parse ISO 8601 string with fromisoformat (Python 3.11+)
                # fromisoformat does not parse 'Z', so replace it with +00:00
                s = v
                if s.endswith('Z'):
                    s = s[:-1] + '+00:00'
                dt = datetime.fromisoformat(s)
            except Exception as e:
                raise ValueError(f"issued_at must be a valid ISO 8601 datetime string or datetime object: {v}") from e
        else:
            raise ValueError(f"issued_at must be a datetime or ISO 8601 string, got {type(v)}")

        # If naive, assume UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt

    def issued_at_str(self) -> str:
        # Format as "YYYY-MM-DDTHH:MM:SSZ" in UTC
        dt = self.issued_at
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt.strftime('%Y-%m-%dT%H:%M:%SZ')

    def total(self) -> Decimal:
        total = Decimal('0')
        for line in self.lines:
            total += line.unit_price * line.quantity
        return total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)


def export_invoice(data: dict) -> str:
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError as e:
        # Raise ValueError as requested
        raise ValueError(e) from e

    out = {
        "number": invoice.number,
        "issued_at": invoice.issued_at_str(),
        "lines": [
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit_price": line.unit_price_str(),
            }
            for line in invoice.lines
        ],
        "total": f"{invoice.total():.2f}",
    }

    import json
    return json.dumps(out, separators=(',', ':'))

from typing import Any, Optional
from pydantic import BaseModel, Field, ValidationError, field_validator


class Profile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    model_config = {
        "from_attributes": True,
    }

    @field_validator("display_name")
    @classmethod
    def collapse_whitespace(cls, v: str) -> str:
        # Collapse internal whitespace to single spaces and strip ends
        collapsed = " ".join(v.split())
        if not collapsed:
            raise ValueError("display_name must not be blank")
        return collapsed

    @field_validator("zip_code", mode="before")
    @classmethod
    def ensure_str_zip_code(cls, v: Any) -> str:
        # Accept int or str, always return str
        if isinstance(v, int):
            return str(v)
        if isinstance(v, str):
            return v
        raise TypeError("zip_code must be str or int")


def import_profiles(rows: list) -> list:
    valid_profiles = []
    for row in rows:
        try:
            profile = Profile.model_validate(row)
        except ValidationError:
            continue
        valid_profiles.append(profile.model_dump())
    return valid_profiles

from typing import List
from pydantic import BaseModel


class CustomerModel(BaseModel):
    id: int
    name: str
    email: str

    model_config = {
        "from_attributes": True,
        "extra": "forbid",
    }


class ItemModel(BaseModel):
    sku: str
    quantity: int

    model_config = {
        "from_attributes": True,
        "extra": "forbid",
    }


class OrderModel(BaseModel):
    id: int
    customer: CustomerModel
    items: List[ItemModel]

    model_config = {
        "from_attributes": True,
        "extra": "forbid",
    }


def orders_payload(orders: list) -> list:
    try:
        validated_orders = [OrderModel.model_validate(order).model_dump() for order in orders]
    except Exception as e:
        # Pydantic ValidationError is a subclass of ValueError, so we can raise it directly
        raise ValueError(str(e)) from e
    return validated_orders

import re
from pydantic import BaseModel, Field, ValidationError, field_validator


class SignupModel(BaseModel):
    username: str = Field(..., pattern=r'^[a-z0-9_]{3,20}$')
    email: str
    phone: str
    password: str = Field(..., min_length=8)
    password_confirm: str

    model_config = {
        'populate_by_name': True,
    }

    @field_validator('email')
    @classmethod
    def validate_email(cls, v: str) -> str:
        if '@' not in v:
            raise ValueError('email must contain "@"')
        return v.strip().lower()

    @field_validator('phone')
    @classmethod
    def validate_phone(cls, v: str) -> str:
        # Remove spaces, dots, dashes, parentheses
        compact = re.sub(r'[ .\-\(\)]', '', v)
        if not re.fullmatch(r'\+\d{8,15}', compact):
            raise ValueError('phone must be "+" followed by 8-15 digits after removing spaces, dots, dashes, parentheses')
        return compact

    @field_validator('password_confirm')
    @classmethod
    def passwords_match(cls, v: str, info) -> str:
        # info.data contains all fields validated so far
        password = info.data.get('password')
        if password is None:
            # password validation will catch missing password
            return v
        if v != password:
            raise ValueError('password_confirm must equal password')
        return v


def validate_signup(data: dict) -> dict:
    m = SignupModel.model_validate(data)
    return {
        'username': m.username,
        'email': m.email,
        'phone': m.phone,
    }
